const threadByCommit = `-- name: ThreadByCommit :one
SELECT tc.thread_id FROM thread_commits tc
JOIN threads t ON t.id = tc.thread_id JOIN projects p ON p.id = t.project_id
WHERE tc.sha = ?1 AND p.github_repo_id = ?2 AND t.archived_at IS NULL
ORDER BY COALESCE(t.last_message_at, t.created_at) DESC LIMIT 1
`

type ThreadByCommitParams struct {
	Sha    string `json:"sha"`
	RepoID *int64 `json:"repoId"`
}

// When several threads sampled the same commit, only the most recently active one counts.
func (q *Queries) ThreadByCommit(ctx context.Context, arg ThreadByCommitParams) (string, error) {
	row := q.db.QueryRowContext(ctx, threadByCommit, arg.Sha, arg.RepoID)
	var thread_id string
	err := row.Scan(&thread_id)
	return thread_id, err
}

